//! `ID_Start` and `ID_Continue` above U+007F, for the executable lexer.
//!
//! The tables are [`super::unicode_data`], generated by `cargo xtask
//! tables` (`xtask/src/js_idents.rs`) from Unicode 18.0.0's
//! `DerivedCoreProperties.txt`. A lookup is a bisection over a table's
//! rows.
//!
//! **What is claimed:** nothing about agreement with the spec. The spec
//! leaves `ID_Start` and `ID_Continue` above U+007F uninterpreted
//! ([`super::spec::unicode_id_start_non_ascii`],
//! [`super::spec::unicode_id_continue_non_ascii`]: the standard says "the
//! latest version of the Unicode Standard"), and no axiom ties them to
//! these tables. Verus proves only that a lookup is total and answers
//! false outside U+0080..U+10FFFF. That the tables are the properties of
//! Unicode 18.0.0 rests on the generator, which `cargo xtask check` reruns,
//! and on the tests in `tests/unicode_tables.rs`.

use super::unicode_data::*;
#[allow(unused_imports)]
use vstd::prelude::*;

verus! {

/// A row of a table: the code points `first..=last`.
#[derive(Clone, Copy)]
pub struct Range {
    /// The first code point of the row.
    pub first: u32,
    /// The last code point of the row.
    pub last: u32,
}

/// Whether a row of the `ID_Start` table holds `c`, by bisection.
fn find_start(c: u32) -> (r: bool) {
    let mut lo: usize = 0;
    let mut hi: usize = ID_START_LEN;
    while lo < hi
        invariant
            lo <= hi <= ID_START_LEN,
        decreases hi - lo,
    {
        // Never saturates: lo < hi.
        let mid = lo.saturating_add(hi.saturating_sub(lo) / 2);
        let row = id_start_at_exec(mid);
        if c < row.first {
            hi = mid;
        } else if c > row.last {
            lo = mid.saturating_add(1);
        } else {
            return true;
        }
    }
    false
}

/// Whether a row of the `ID_Continue` table holds `c`, by bisection.
fn find_continue(c: u32) -> (r: bool) {
    let mut lo: usize = 0;
    let mut hi: usize = ID_CONTINUE_LEN;
    while lo < hi
        invariant
            lo <= hi <= ID_CONTINUE_LEN,
        decreases hi - lo,
    {
        // Never saturates: lo < hi.
        let mid = lo.saturating_add(hi.saturating_sub(lo) / 2);
        let row = id_continue_at_exec(mid);
        if c < row.first {
            hi = mid;
        } else if c > row.last {
            lo = mid.saturating_add(1);
        } else {
            return true;
        }
    }
    false
}

/// Whether `c` (above U+007F) has the Unicode property `ID_Start`.
pub fn id_start_non_ascii(c: u32) -> (r: bool)
    ensures
        r ==> 0x80 <= c <= 0x10FFFF,
{
    if c < 0x80 {
        return false;
    }
    if c > 0x10FFFF {
        return false;
    }
    find_start(c)
}

/// Whether `c` (above U+007F) has the Unicode property `ID_Continue`.
pub fn id_continue_non_ascii(c: u32) -> (r: bool)
    ensures
        r ==> 0x80 <= c <= 0x10FFFF,
{
    if c < 0x80 {
        return false;
    }
    if c > 0x10FFFF {
        return false;
    }
    find_continue(c)
}

} // verus!
